<?php
require_once __DIR__.'/../includes/auth.php';require_role(['super_admin','manager']);$bid=current_branch_id();$serviceDays=rule_int('equipment_warning_days',7);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';
 if($action==='add'){$code='EQ-'.random_int(100,999);db()->prepare("INSERT INTO equipment(branch_id,asset_code,name,category,purchase_date,purchase_price,condition_status,last_service,next_service,location,notes) VALUES(?,?,?,?,?,?,?,?,?,?,?)")->execute([$bid,$code,trim($_POST['name']),trim($_POST['category']),$_POST['purchase_date']?:null,(float)($_POST['purchase_price']??0),$_POST['condition_status'],$_POST['last_service']?:null,$_POST['next_service']?:null,trim($_POST['location']),trim($_POST['notes'])]);$id=(int)db()->lastInsertId();audit_log('equipment.created','equipment',$id,$code.' added');flash('success','Equipment added.');redirect('app/equipment.php');}
 if($action==='status'){$id=(int)$_POST['id'];db()->prepare('UPDATE equipment SET condition_status=? WHERE id=? AND branch_id=?')->execute([$_POST['condition_status'],$id,$bid]);audit_log('equipment.status','equipment',$id,'Condition changed to '.$_POST['condition_status']);flash('success','Equipment status updated.');redirect('app/equipment.php');}
 if($action==='service'){$id=(int)$_POST['equipment_id'];$exists=query_value('SELECT COUNT(*) FROM equipment WHERE id=? AND branch_id=?',[$id,$bid]);if($exists){db()->beginTransaction();try{db()->prepare("INSERT INTO equipment_maintenance(equipment_id,service_date,service_type,vendor,cost,notes,next_service,created_by) VALUES(?,?,?,?,?,?,?,?)")->execute([$id,$_POST['service_date'],trim($_POST['service_type']),trim($_POST['vendor']??''),(float)($_POST['cost']??0),trim($_POST['notes']??''),$_POST['next_service']?:null,user()['id']]);db()->prepare("UPDATE equipment SET last_service=?,next_service=?,condition_status=? WHERE id=?")->execute([$_POST['service_date'],$_POST['next_service']?:null,$_POST['condition_status'],$id]);db()->commit();audit_log('equipment.serviced','equipment',$id,'Maintenance/service record added');flash('success','Service history recorded.');}catch(Throwable $e){db()->rollBack();flash('danger','Could not save service record.');}}redirect('app/equipment.php');}
}
$rows=query_all('SELECT e.*,(SELECT COUNT(*) FROM equipment_maintenance x WHERE x.equipment_id=e.id) service_count FROM equipment e WHERE e.branch_id=? ORDER BY e.next_service IS NULL,e.next_service,e.asset_code',[$bid]);
$history=query_all("SELECT h.*,e.asset_code,e.name equipment_name,u.name created_by_name FROM equipment_maintenance h JOIN equipment e ON e.id=h.equipment_id LEFT JOIN users u ON u.id=h.created_by WHERE e.branch_id=? ORDER BY h.service_date DESC,h.id DESC LIMIT 50",[$bid]);
$good=(int)query_value("SELECT COUNT(*) FROM equipment WHERE branch_id=? AND condition_status='good'",[$bid]);$maint=(int)query_value("SELECT COUNT(*) FROM equipment WHERE branch_id=? AND condition_status='maintenance'",[$bid]);$dam=(int)query_value("SELECT COUNT(*) FROM equipment WHERE branch_id=? AND condition_status='damaged'",[$bid]);$due=(int)query_value("SELECT COUNT(*) FROM equipment WHERE branch_id=? AND next_service<=DATE_ADD(CURDATE(),INTERVAL $serviceDays DAY) AND condition_status<>'retired'",[$bid]);$value=(float)query_value("SELECT COALESCE(SUM(purchase_price),0) FROM equipment WHERE branch_id=? AND condition_status<>'retired'",[$bid]);$serviceCost=(float)query_value("SELECT COALESCE(SUM(h.cost),0) FROM equipment_maintenance h JOIN equipment e ON e.id=h.equipment_id WHERE e.branch_id=? AND h.service_date>=DATE_FORMAT(CURDATE(),'%Y-%m-01')",[$bid]);
$pageTitle='Equipment & Maintenance';include __DIR__.'/../includes/header.php'; ?>
<div class="metric-strip"><div class="metric-box"><small>Good condition</small><strong><?= $good ?></strong></div><div class="metric-box"><small>Maintenance / damaged</small><strong><?= $maint+$dam ?></strong></div><div class="metric-box"><small>Service cost this month</small><strong><?= money($serviceCost) ?></strong></div><div class="metric-box"><small>Asset value</small><strong><?= money($value) ?></strong></div></div>
<div class="page-actions"><button class="btn btn-primary" data-bs-toggle="modal" data-bs-target="#equipModal"><i class="fa-solid fa-plus me-2"></i>Add equipment</button><button class="btn btn-dark" data-bs-toggle="modal" data-bs-target="#serviceModal"><i class="fa-solid fa-screwdriver-wrench me-2"></i>Record service</button></div>
<div class="table-card"><div class="table-toolbar"><div><strong>Asset register</strong><div class="text-muted" style="font-size:.68rem"><?= $due ?> service item(s) due within <?= $serviceDays ?> days</div></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Asset</th><th>Category</th><th>Location</th><th>Last service</th><th>Next service</th><th>History</th><th>Condition</th><th class="text-end">Update</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><strong><?= e($r['name']) ?></strong><div class="text-muted" style="font-size:.64rem"><?= e($r['asset_code']) ?></div></td><td><?= e($r['category']) ?></td><td><?= e($r['location']) ?></td><td><?= format_date($r['last_service']) ?></td><td><?= format_date($r['next_service']) ?></td><td><?= (int)$r['service_count'] ?> record(s)</td><td><span class="badge-soft badge-<?= status_badge($r['condition_status']) ?>"><?= e(ucfirst($r['condition_status'])) ?></span></td><td class="text-end"><form method="post" class="d-flex gap-1 justify-content-end"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="status"><input type="hidden" name="id" value="<?= $r['id'] ?>"><select name="condition_status" class="form-select form-select-sm" style="width:140px"><option value="good" <?= $r['condition_status']==='good'?'selected':'' ?>>Good</option><option value="maintenance" <?= $r['condition_status']==='maintenance'?'selected':'' ?>>Maintenance</option><option value="damaged" <?= $r['condition_status']==='damaged'?'selected':'' ?>>Damaged</option><option value="retired" <?= $r['condition_status']==='retired'?'selected':'' ?>>Retired</option></select><button class="action-btn"><i class="fa-solid fa-check"></i></button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<div class="table-card mt-3"><div class="table-toolbar"><div><strong>Maintenance history</strong><div class="text-muted" style="font-size:.68rem">Service, repair cost and next due date</div></div></div><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Equipment</th><th>Service</th><th>Vendor</th><th>Cost</th><th>Next service</th><th>Recorded by</th></tr></thead><tbody><?php foreach($history as $h):?><tr><td><?= format_date($h['service_date']) ?></td><td><strong><?= e($h['equipment_name']) ?></strong><small class="d-block text-muted"><?= e($h['asset_code']) ?></small></td><td><?= e($h['service_type']) ?></td><td><?= e($h['vendor']?:'—') ?></td><td><?= money($h['cost']) ?></td><td><?= format_date($h['next_service']) ?></td><td><?= e($h['created_by_name']??'System') ?></td></tr><?php endforeach;if(!$history):?><tr><td colspan="7" class="text-muted">No maintenance history yet.</td></tr><?php endif;?></tbody></table></div></div>
<div class="modal fade" id="equipModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="add"><div class="modal-header"><h5>Add equipment</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-12"><label class="form-label">Equipment name</label><input name="name" class="form-control" required></div><div class="col-6"><label class="form-label">Category</label><input name="category" class="form-control"></div><div class="col-6"><label class="form-label">Location</label><input name="location" class="form-control"></div><div class="col-6"><label class="form-label">Purchase date</label><input type="date" name="purchase_date" class="form-control"></div><div class="col-6"><label class="form-label">Purchase price</label><input type="number" step=".01" name="purchase_price" class="form-control"></div><div class="col-6"><label class="form-label">Condition</label><select name="condition_status" class="form-select"><option value="good">Good</option><option value="maintenance">Maintenance</option><option value="damaged">Damaged</option></select></div><div class="col-6"><label class="form-label">Last service</label><input type="date" name="last_service" class="form-control"></div><div class="col-12"><label class="form-label">Next service</label><input type="date" name="next_service" class="form-control"></div><div class="col-12"><label class="form-label">Notes</label><textarea name="notes" class="form-control" rows="2"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-primary">Add asset</button></div></form></div></div></div>
<div class="modal fade" id="serviceModal"><div class="modal-dialog modal-dialog-centered"><div class="modal-content"><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><input type="hidden" name="action" value="service"><div class="modal-header"><h5>Record equipment service</h5><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><div class="row g-3"><div class="col-12"><label class="form-label">Equipment</label><select name="equipment_id" class="form-select"><?php foreach($rows as $r):?><option value="<?= $r['id'] ?>"><?= e($r['asset_code'].' — '.$r['name']) ?></option><?php endforeach;?></select></div><div class="col-6"><label class="form-label">Service date</label><input type="date" name="service_date" value="<?= date('Y-m-d') ?>" class="form-control" required></div><div class="col-6"><label class="form-label">Service type</label><input name="service_type" class="form-control" value="Preventive service" required></div><div class="col-6"><label class="form-label">Vendor</label><input name="vendor" class="form-control"></div><div class="col-6"><label class="form-label">Cost</label><input type="number" step=".01" name="cost" value="0" class="form-control"></div><div class="col-6"><label class="form-label">Next service</label><input type="date" name="next_service" class="form-control"></div><div class="col-6"><label class="form-label">Condition after service</label><select name="condition_status" class="form-select"><option value="good">Good</option><option value="maintenance">Maintenance</option><option value="damaged">Damaged</option></select></div><div class="col-12"><label class="form-label">Notes</label><textarea name="notes" class="form-control" rows="2"></textarea></div></div></div><div class="modal-footer"><button class="btn btn-primary">Save service record</button></div></form></div></div></div>
<?php include __DIR__.'/../includes/footer.php'; ?>